<script>
// --- Prototype-only simulation of "the app picks up the page title automatically" ---
// A small canned lookup so the auto-fill feels real during review. Unknown hosts
// fall back to a readable title derived from the address.
const KNOWN = {
  "developer.mozilla.org": { title: "MDN Web Docs", desc: "Resources for developers, by developers." },
  "github.com": { title: "GitHub", desc: "Let's build from here — the world's largest developer platform." },
  "en.wikipedia.org": { title: "Wikipedia, the free encyclopedia", desc: "The free encyclopedia anyone can edit." },
  "www.nytimes.com": { title: "The New York Times — Breaking News", desc: "Live news, investigations, opinion, photos and video." },
  "news.ycombinator.com": { title: "Hacker News", desc: "News and discussion for the tech community." }
};
function normalizeUrl(raw){
  let s = raw.trim();
  if(!s) return null;
  if(!/^https?:\/\//i.test(s)) s = "https://" + s;
  try { return new URL(s); } catch(e){ return null; }
}
function fakeFetchInfo(u){
  const host = u.hostname.replace(/^www\./,'');
  const known = KNOWN[u.hostname] || KNOWN[host];
  if(known) return known;
  const path = u.pathname.replace(/\/$/,'').split('/').filter(Boolean).pop() || host;
  const pretty = decodeURIComponent(path).replace(/[-_]/g,' ').replace(/\.\w+$/,'');
  const title = pretty.charAt(0).toUpperCase() + pretty.slice(1) + " — " + host;
  return { title, desc: "" };
}

const bookmarks = [];
const listEl = document.getElementById('list');
const statusEl = document.getElementById('status');
const urlEl = document.getElementById('url');
const saveBtn = document.getElementById('save');

function render(){
