    el.className = 'bm' + (b.flash ? ' flash' : '');
    el.innerHTML = `<p class="title"></p><div class="url"></div>` +
      (b.desc ? `<p class="desc"></p>` : '') +
      `<div class="meta">Saved just now</div>`;
    el.querySelector('.title').textContent = b.title;
    el.querySelector('.url').textContent = b.url;
    if(b.desc) el.querySelector('.desc').textContent = b.desc;
    listEl.appendChild(el);
    b.flash = false;
  });
}

function save(){
  const u = normalizeUrl(urlEl.value);
  if(!u){ statusEl.textContent = "That doesn't look like a valid link yet."; return; }
  saveBtn.disabled = true;
  statusEl.textContent = "Fetching page details…";
  setTimeout(() => {
    const info = fakeFetchInfo(u);
    bookmarks.unshift({ url: u.href, title: info.title, desc: info.desc, flash: true });
    render();
    statusEl.textContent = "Saved — title picked up automatically.";
    urlEl.value = "";
    saveBtn.disabled = false;
    urlEl.focus();
  }, 550);
}

saveBtn.addEventListener('click', save);
urlEl.addEventListener('keydown', e => { if(e.key === 'Enter') save(); });

render();
document.body.setAttribute('data-harness-ready','true');
